/* ============================================================
   THE HOLLOW CROWN — procedural 16-bit sound
   ============================================================ */
let ctx = null;
let master = null;
let muted = false;
try { muted = localStorage.getItem('hollow-crown-muted') === '1'; } catch { /* ignore */ }

function ensure() {
  if (muted) return null;
  if (!ctx) {
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return null;
    ctx = new AC();
    master = ctx.createGain();
    master.gain.value = 0.16;
    master.connect(ctx.destination);
  }
  if (ctx.state === 'suspended') ctx.resume().catch(() => {});
  return ctx;
}

function tone(freq, dur, type = 'square', vol = 0.5, slide = 0, delay = 0) {
  const c = ensure();
  if (!c) return;
  const t0 = c.currentTime + delay;
  const osc = c.createOscillator();
  const gain = c.createGain();
  osc.type = type;
  osc.frequency.setValueAtTime(freq, t0);
  if (slide) osc.frequency.exponentialRampToValueAtTime(Math.max(30, freq + slide), t0 + dur);
  gain.gain.setValueAtTime(0.0001, t0);
  gain.gain.exponentialRampToValueAtTime(vol, t0 + 0.01);
  gain.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
  osc.connect(gain);
  gain.connect(master);
  osc.start(t0);
  osc.stop(t0 + dur + 0.02);
}

function noise(dur = 0.12, vol = 0.5, low = false) {
  const c = ensure();
  if (!c) return;
  const len = Math.floor(c.sampleRate * dur);
  const buffer = c.createBuffer(1, len, c.sampleRate);
  const data = buffer.getChannelData(0);
  for (let i = 0; i < len; i++) data[i] = (Math.random() * 2 - 1) * (1 - i / len);
  const src = c.createBufferSource();
  src.buffer = buffer;
  const filter = c.createBiquadFilter();
  filter.type = low ? 'lowpass' : 'highpass';
  filter.frequency.value = low ? 500 : 900;
  const gain = c.createGain();
  gain.gain.value = vol;
  src.connect(filter);
  filter.connect(gain);
  gain.connect(master);
  src.start();
}

export function sfx(name) {
  if (muted) return;
  switch (name) {
    case 'click': tone(420, 0.04, 'square', 0.3); break;
    case 'hover': tone(600, 0.02, 'square', 0.12); break;
    case 'move': tone(220, 0.05, 'triangle', 0.25, 30); break;
    case 'hit':
      noise(0.12, 0.55, true);
      tone(120, 0.12, 'square', 0.4, -50);
      break;
    case 'crit':
      noise(0.16, 0.7, false);
      tone(180, 0.16, 'sawtooth', 0.45, -90);
      break;
    case 'magic':
      tone(540, 0.22, 'sine', 0.3, 260);
      tone(270, 0.18, 'triangle', 0.2, -80, 0.02);
      break;
    case 'heal':
      tone(520, 0.12, 'sine', 0.28, 120);
      tone(780, 0.18, 'sine', 0.22, 160, 0.08);
      break;
    case 'buff':
      tone(330, 0.12, 'triangle', 0.24, 90);
      tone(495, 0.18, 'triangle', 0.2, 90, 0.08);
      break;
    case 'debuff':
      tone(300, 0.18, 'sawtooth', 0.2, -120);
      break;
    case 'turn':
      tone(392, 0.08, 'square', 0.22);
      tone(523, 0.12, 'square', 0.2, 0, 0.08);
      break;
    case 'enemyTurn':
      tone(196, 0.1, 'square', 0.22);
      tone(147, 0.14, 'square', 0.2, 0, 0.09);
      break;
    case 'select': tone(660, 0.04, 'square', 0.18); break;
    case 'cancel': tone(220, 0.06, 'square', 0.18, -40); break;
    case 'victory':
      [523, 659, 784, 1046].forEach((f, i) => tone(f, 0.22, 'square', 0.22, 0, i * 0.1));
      break;
    case 'defeat':
      [330, 294, 262, 196].forEach((f, i) => tone(f, 0.3, 'triangle', 0.25, -20, i * 0.14));
      break;
    case 'levelup':
      [523, 659, 784, 1046, 1318].forEach((f, i) => tone(f, 0.14, 'square', 0.2, 0, i * 0.06));
      break;
    case 'loot':
      tone(880, 0.08, 'square', 0.2);
      tone(1174, 0.14, 'square', 0.18, 0, 0.07);
      break;
    default: break;
  }
}

export function isMuted() { return muted; }
export function toggleMute() {
  muted = !muted;
  try { localStorage.setItem('hollow-crown-muted', muted ? '1' : '0'); } catch { /* ignore */ }
  if (!muted) sfx('click');
  return muted;
}
export function initAudio() { ensure(); }

/* ============================================================
   THE HOLLOW CROWN — shared UI helpers
   ============================================================ */
export const $ = (sel, root = document) => root.querySelector(sel);
export const $$ = (sel, root = document) => Array.from(root.querySelectorAll(sel));

export function showScreen(id) {
  for (const screen of $$('.screen')) screen.classList.toggle('active', screen.id === id);
  const active = document.getElementById(id);
  if (active) active.scrollTop = 0;
}

export function esc(s) {
  return String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}

let toastEl = null;
let toastTimer = 0;
export function toast(message, ms = 2200) {
  if (!toastEl) {
    toastEl = document.createElement('div');
    toastEl.className = 'toast';
    toastEl.id = 'global-toast';
    document.body.appendChild(toastEl);
  }
  toastEl.textContent = message;
  toastEl.classList.add('show');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => toastEl.classList.remove('show'), ms);
}

/* ---------- modal ---------- */
let modalMount = null;
let modalKeyHandler = null;

export function openModal({ title, body, footer = '', onMount = null, wide = false }) {
  const root = document.getElementById('modal-root');
  if (!root) return;
  root.innerHTML = `
    <div class="modal-card" role="document" ${wide ? 'style="width:min(1040px,97vw)"' : ''}>
      <div class="modal-head">
        <h2>${esc(title)}</h2>
        <button class="modal-close" data-close aria-label="Close">×</button>
      </div>
      <div class="modal-body">${body}</div>
      ${footer ? `<div class="modal-body" style="padding-top:0">${footer}</div>` : ''}
    </div>`;
  root.classList.remove('hidden');
  const card = root.querySelector('.modal-card');
  const close = () => closeModal();
  root.querySelectorAll('[data-close]').forEach(b => b.addEventListener('click', close));
  root.onclick = (e) => { if (e.target === root) close(); };
  modalKeyHandler = (e) => { if (e.key === 'Escape') close(); };
  document.addEventListener('keydown', modalKeyHandler);
  modalMount = onMount;
  if (onMount) onMount(card, root);
  return card;
}

export function closeModal() {
  const root = document.getElementById('modal-root');
  if (!root) return;
  root.classList.add('hidden');
  root.innerHTML = '';
  root.onclick = null;
  if (modalKeyHandler) document.removeEventListener('keydown', modalKeyHandler);
  modalKeyHandler = null;
  modalMount = null;
}

export function confirmDialog({ title = 'Confirm', text = '', confirm = 'Confirm', cancel = 'Cancel', danger = false }) {
  return new Promise(resolve => {
    let settled = false;
    const done = (v) => {
      if (settled) return;
      settled = true;
      closeModal();
      resolve(v);
    };
    const card = openModal({
      title,
      body: `<p class="dialog-text">${esc(text)}</p>`,
      footer: `<div class="dialog-actions">
        <button class="btn ghost" data-act="cancel">${esc(cancel)}</button>
        <button class="btn ${danger ? 'danger' : 'gold'}" data-act="ok">${esc(confirm)}</button>
      </div>`,
    });
    card.querySelector('[data-act="cancel"]').onclick = () => done(false);
    card.querySelector('[data-act="ok"]').onclick = () => done(true);
    card.querySelector('.modal-close').addEventListener('click', () => done(false));
    // Esc / backdrop also resolve false
    const oldClose = document.getElementById('modal-root');
    oldClose.addEventListener('click', (e) => { if (e.target === oldClose) done(false); });
  });
}

/* ---------- formatting ---------- */
export const STAT_NAMES = { maxHp: 'HP', maxMp: 'MP', pa: 'PA', ma: 'MA', def: 'DEF', res: 'RES', spd: 'SPD', move: 'MOV', jump: 'JMP', luck: 'LUK' };

export function bar(value, max, cls = 'hp') {
  const pct = Math.max(0, Math.min(100, (value / Math.max(1, max)) * 100));
  return `<div class="bar"><div class="bar-fill ${cls}" style="width:${pct}%"></div></div>`;
}

export function statusLabel(id) {
  return {
    stun: 'Stun', slow: 'Slow', haste: 'Haste', poison: 'Poison', burn: 'Burn',
    regen: 'Regen', defUp: 'DEF+', atkUp: 'PA+', silence: 'Silence', shield: 'Shield',
    defDown: 'DEF-', ward: 'RES+', evade: 'Evade', riposte: 'Riposte', focus: 'Focus',
  }[id] || id;
}

export function statusKind(id) {
  return ['poison', 'burn', 'slow', 'silence', 'defDown', 'stun'].includes(id) ? 'bad' : 'good';
}

export function itemStatLine(item) {
  if (!item) return '';
  const parts = [];
  if (item.atk) parts.push(`ATK ${item.atk}`);
  if (item.mag) parts.push(`MAG ${item.mag}`);
  if (item.range) parts.push(`RNG ${item.range}`);
  if (item.def) parts.push(`DEF ${item.def}`);
  if (item.res) parts.push(`RES ${item.res}`);
  if (item.hp) parts.push(`HP ${item.hp}`);
  if (item.mp) parts.push(`MP ${item.mp}`);
  if (item.spd) parts.push(`SPD ${item.spd}`);
  if (item.move) parts.push(`MOV ${item.move}`);
  return parts.join(' · ');
}

export function levelProgress(exp, level) {
  const need = 42 + level * 19;
  return { exp, need, pct: Math.min(100, (exp / need) * 100) };
}

