219:   }
220:   return { ok: true };
221: }
222: 
223: export function equipItem(state, unit, slot, itemId) {
224:   if (!itemId) { unit.equipment[slot] = null; return { ok: true }; }
225:   const check = canEquipItem(state, unit, slot, itemId);
226:   if (!check.ok) return check;
227:   unit.equipment[slot] = itemId;
228:   return { ok: true };
229: }
230: 
231: export function buyItem(state, itemId, qty = 1) {
232:   const item = ITEM_MAP[itemId];
233:   if (!item) return { ok: false, reason: 'Unknown item' };
234:   const cost = item.cost * qty;
235:   if (state.gold < cost) return { ok: false, reason: 'Not enough gold' };
236:   state.gold -= cost;
237:   addItem(state, itemId, qty);
238:   return { ok: true, item, cost };
239: }
240: 
241: export function gearForShop(state) {
242:   return EQUIPMENT.filter(i => owned(state, i.id) > 0);
243: }
244: 
245: /* ------------------------------------------------------------
246:    Progression
247:    ------------------------------------------------------------ */
248: export function expNeeded(level) { return 42 + level * 19; }
249: 
250: export function grantExp(unit, amount) {
251:   unit.exp += amount;
252:   let gained = 0;
253:   while (unit.level < 20 && unit.exp >= expNeeded(unit.level)) {
254:     unit.exp -= expNeeded(unit.level);
255:     unit.level += 1;
256:     gained += 1;
257:     unit.base.hp += 6;
258:     unit.base.mp += 3;
259:     unit.base.pa += 1;
260:     if (unit.level % 2 === 0) unit.base.def += 1;
261:     if (unit.level % 3 === 0) { unit.base.ma += 1; unit.base.res += 1; }
262:     if (unit.level % 4 === 0) unit.base.spd += 1;
263:   }
264:   if (unit.level >= 20) unit.exp = Math.min(unit.exp, expNeeded(20) - 1);
265:   return gained;
266: }
267: 
268: export function grantJp(unit, amount) { unit.jp += amount; }
269: 
270: export function recruitUnit(state, templateId) {
271:   if (state.roster.some(u => u.id === templateId)) return null;
272:   const tpl = ROSTER.find(r => r.id === templateId);
273:   if (!tpl) return null;
274:   const deployedCount = state.roster.filter(u => u.deployed).length;
275:   const unit = makeUnit(tpl, deployedCount < MAX_DEPLOY);
276:   state.roster.push(unit);
277:   for (const id of Object.values(unit.equipment)) if (id) addItem(state, id, 1);
278:   return unit;
279: }
280: 
281: export function toggleDeploy(state, unitId) {
282:   const unit = state.roster.find(u => u.id === unitId);
283:   if (!unit) return { ok: false };
284:   if (!unit.deployed && state.roster.filter(u => u.deployed).length >= MAX_DEPLOY) {
285:     return { ok: false, reason: `Only ${MAX_DEPLOY} may march` };
286:   }
287:   if (unit.deployed && state.roster.filter(u => u.deployed).length <= 1) {
288:     return { ok: false, reason: 'At least one must march' };
289:   }
290:   unit.deployed = !unit.deployed;
291:   return { ok: true, deployed: unit.deployed };
292: }
293: 
294: export function deployedUnits(state) {
295:   return state.roster.filter(u => u.deployed);
296: }
297: 
298: export function currentEncounter(state) {
299:   return ENCOUNTERS[state.encounterIndex] || null;
300: }
301: 
302: export function advanceEncounter(state) {
303:   state.encounterIndex += 1;
304:   if (state.encounterIndex >= ENCOUNTERS.length) state.completed = true;
305: }
306: 
307: /* ------------------------------------------------------------
308:    Save / load
309:    ------------------------------------------------------------ */
310: export function saveGame(state) {
311:   try {
312:     state.updatedAt = Date.now();
313:     localStorage.setItem(SAVE_KEY, JSON.stringify(state));
314:     return true;
315:   } catch { return false; }
316: }
317: 
318: export function loadGame() {
319:   try {
320:     const raw = localStorage.getItem(SAVE_KEY);
321:     if (!raw) return null;
322:     const state = JSON.parse(raw);
323:     if (!state || !Array.isArray(state.roster)) return null;
324:     state.inventory = state.inventory || {};
325:     state.stats = state.stats || { battles: 0, victories: 0, kills: 0, goldEarned: 0, turns: 0 };
326:     state.seenIntros = state.seenIntros || [];
327:     state.encounterIndex = Math.min(state.encounterIndex || 0, ENCOUNTERS.length);
328:     for (const u of state.roster) {
329:       u.arts = u.arts || {};
330:       u.equipment = u.equipment || {};
331:       if (u.deployed === undefined) u.deployed = true;
332:       if (u.promoted === undefined) u.promoted = false;
333:       if (u.advancedJob === undefined) u.advancedJob = null;
334:       if (!Array.isArray(u.unlockedJobs)) u.unlockedJobs = [];
335:       if (JOBS[u.job]?.tier && !u.unlockedJobs.includes(u.job)) u.unlockedJobs.push(u.job);
336:     }
337:     if (state.completed === undefined) state.completed = state.encounterIndex >= ENCOUNTERS.length;
338:     return state;
339:   } catch { return null; }
340: }
341: 
342: export function hasSave() {
343:   try { return !!localStorage.getItem(SAVE_KEY); } catch { return false; }
344: }
345: 
346: export function clearSave() {
347:   try { localStorage.removeItem(SAVE_KEY); } catch { /* ignore */ }
348: }

